#Requires -Version 5.1
<#
  CineVerse by NetStreaming - instalator all-in-one pentru Windows 10/11 si Windows Server.
  Instaleaza serverul media (filme, seriale, TV Live) ca serviciu care porneste odata cu Windows.

  Utilizare:
    Clic dreapta pe fisier -> "Run with PowerShell"   (sau, intr-un PowerShell de administrator:)
    powershell -ExecutionPolicy Bypass -File CineVerse-Install.ps1

  Optiuni:
    -Port 8200            portul web
    -Media "D:\Filme;D:\Seriale"
    -AdminUser admin -AdminPass parola
    -ResetAdmin           schimba contul de administrator
    -Uninstall            dezinstaleaza (baza de date se pastreaza, te intreaba)
#>
[CmdletBinding()]
param(
  [int]$Port = 0,
  [string]$Media = "",
  [string]$AdminUser = "",
  [string]$AdminPass = "",
  [string]$TmdbKey = "",
  [string]$OsKey = "",
  [switch]$ResetAdmin,
  [switch]$Uninstall
)

$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor [Net.SecurityProtocolType]::Tls11

# ------------------------------------------------------------------ constante
$AppName  = "CineVerse"
$App      = Join-Path $env:ProgramFiles $AppName
$Data     = Join-Path $env:ProgramData $AppName
$TaskName = "CineVerse Server"
$PyVer    = "3.12.10"
$PyUrl    = "https://www.python.org/ftp/python/$PyVer/python-$PyVer-embed-amd64.zip"
$PipUrls  = @(
  "https://bootstrap.pypa.io/get-pip.py",
  "https://raw.githubusercontent.com/pypa/get-pip/main/public/get-pip.py"
)
$FfUrls   = @(
  "https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-win64-gpl.zip",
  "https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip"
)
$HlsUrls  = @(
  "https://cdn.jsdelivr.net/npm/hls.js@1/dist/hls.min.js",
  "https://unpkg.com/hls.js@1/dist/hls.min.js"
)

# ------------------------------------------------------------------ afisare
function Say  ($m) { Write-Host "  $m" -ForegroundColor Cyan }
function Ok   ($m) { Write-Host "  [OK] $m" -ForegroundColor Green }
function Warn ($m) { Write-Host "  [!]  $m" -ForegroundColor Yellow }
function Die  ($m) { Write-Host ""; Write-Host "  [X]  $m" -ForegroundColor Red; Write-Host ""; Read-Host "Apasa Enter ca sa inchizi"; exit 1 }
function Title($m) {
  Write-Host ""
  Write-Host ("  " + ("=" * 62)) -ForegroundColor DarkCyan
  Write-Host "   $m" -ForegroundColor White
  Write-Host ("  " + ("=" * 62)) -ForegroundColor DarkCyan
  Write-Host ""
}

# ------------------------------------------------------------------ drepturi de administrator
$me = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $me.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
  Write-Host "  Am nevoie de drepturi de administrator - redeschid PowerShell ridicat..." -ForegroundColor Yellow
  $argList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", "`"$PSCommandPath`"")
  foreach ($kv in $PSBoundParameters.GetEnumerator()) {
    if ($kv.Value -is [switch]) { if ($kv.Value) { $argList += "-$($kv.Key)" } }
    else { $argList += @("-$($kv.Key)", "`"$($kv.Value)`"") }
  }
  try { Start-Process powershell -Verb RunAs -ArgumentList $argList } catch { Die "Nu am putut porni cu drepturi de administrator." }
  exit
}

if ([IntPtr]::Size -ne 8) { Die "Este nevoie de Windows pe 64 de biti." }

# ------------------------------------------------------------------ utilitare
function Get-File($urls, $dest, $what) {
  foreach ($u in @($urls)) {
    for ($try = 1; $try -le 3; $try++) {
      try {
        Invoke-WebRequest -Uri $u -OutFile $dest -UseBasicParsing -TimeoutSec 300
        if ((Get-Item $dest).Length -gt 0) { return $true }
      } catch {
        Start-Sleep -Seconds ([Math]::Min(5, $try * 2))
      }
    }
    Warn "Nu am putut descarca $what de la $u"
  }
  return $false
}

function Write-B64($b64, $path) {
  $dir = Split-Path $path -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String(($b64 -replace '\s', '')))
}

function Stop-CineVerse {
  try {
    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
      Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    }
  } catch {}
  Get-Process -Name python, pythonw -ErrorAction SilentlyContinue |
    Where-Object { $_.Path -and $_.Path.StartsWith($App, [StringComparison]::OrdinalIgnoreCase) } |
    ForEach-Object { try { $_.Kill() } catch {} }
  Start-Sleep -Milliseconds 800
}

function Get-TaskPort {
  # intai lansatorul scris de noi - e sursa cea mai sigura
  $cmd = Join-Path $App "run-cineverse.cmd"
  if (Test-Path $cmd) {
    try {
      $txt = Get-Content $cmd -Raw
      if ($txt -match '--port\s+(\d+)') { return [int]$Matches[1] }
    } catch {}
  }
  try {
    $t = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    if ($t) {
      foreach ($a in $t.Actions) {
        $line = "$($a.Execute) $($a.Arguments)"
        if ($line -match '--port\s+(\d+)') { return [int]$Matches[1] }
      }
    }
  } catch {}
  return 0
}

function Ask($prompt, $default, [switch]$Secret) {
  if ($Secret) {
    $s = Read-Host "  $prompt" -AsSecureString
    $b = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($s)
    try { return [Runtime.InteropServices.Marshal]::PtrToStringAuto($b) }
    finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($b) }
  }
  $hint = if ($default) { " [$default]" } else { "" }
  $v = Read-Host "  $prompt$hint"
  if ([string]::IsNullOrWhiteSpace($v)) { return $default }
  return $v.Trim()
}

$PyExe = Join-Path $App "python\python.exe"
function Invoke-Py {
  param([string[]]$PyArgs, [switch]$Quiet)
  $env:CINEVERSE_DATA = $Data
  $env:CINEVERSE_FFMPEG_DIR = (Join-Path $App "ffmpeg")
  $env:PYTHONUTF8 = "1"
  if ($Quiet) { & $PyExe @PyArgs *>$null } else { & $PyExe @PyArgs }
  return $LASTEXITCODE
}

# ------------------------------------------------------------------ dezinstalare
if ($Uninstall) {
  Title "Dezinstalare $AppName"
  Stop-CineVerse
  try { Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
  try { Get-NetFirewallRule -DisplayName "CineVerse*" -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue } catch {}
  $p = [Environment]::GetEnvironmentVariable("Path", "Machine")
  if ($p -and $p.Contains($App)) {
    [Environment]::SetEnvironmentVariable("Path", (($p -split ';' | Where-Object { $_ -and $_ -ne $App }) -join ';'), "Machine")
  }
  Remove-Item (Join-Path ([Environment]::GetFolderPath("CommonPrograms")) "CineVerse.lnk") -Force -ErrorAction SilentlyContinue
  if (Test-Path $App) { Remove-Item $App -Recurse -Force -ErrorAction SilentlyContinue }
  Ok "Aplicatia a fost stearsa."
  Write-Host ""
  $ans = Ask "Sterg si biblioteca/utilizatorii/setarile din $Data ? (nu/da)" "nu"
  if ($ans -match '^(da|d|y|yes)$') {
    Remove-Item $Data -Recurse -Force -ErrorAction SilentlyContinue
    Ok "Datele au fost sterse."
  } else {
    Ok "Datele raman in $Data (o reinstalare le va gasi)."
  }
  Write-Host ""; Read-Host "Apasa Enter ca sa inchizi"; exit 0
}

# ------------------------------------------------------------------ resetare administrator
if ($ResetAdmin) {
  Title "Resetare cont administrator"
  if (-not (Test-Path (Join-Path $Data "cineverse.db"))) { Die "CineVerse nu este instalat." }
  if (-not (Test-Path $PyExe)) { Die "Instalarea pare incompleta - ruleaza din nou instalatorul." }
  $u = Ask "Nume cont administrator" "admin"
  $p1 = Ask "Parola noua" "" -Secret
  if ($u -eq "" -or $p1.Length -lt 4) { Die "Nume si parola (minim 4 caractere) obligatorii." }
  Invoke-Py @("$App\server.py", "setup", "--admin-user", $u, "--admin-pass", $p1) -Quiet | Out-Null
  try { Stop-ScheduledTask -TaskName $TaskName -EA SilentlyContinue; Start-Sleep 2; Start-ScheduledTask -TaskName $TaskName -EA SilentlyContinue } catch {}
  Ok "Contul '$u' este acum singurul administrator."
  Write-Host ""; Read-Host "Apasa Enter ca sa inchizi"; exit 0
}

# ------------------------------------------------------------------ instalare / actualizare
$GenPass = ""
$IsUpdate = Test-Path (Join-Path $Data "cineverse.db")
Title "$AppName by NetStreaming - $(if ($IsUpdate) { 'actualizare' } else { 'instalare' })"

if ($IsUpdate) {
  Ok "Am gasit o instalare existenta - pastrez biblioteca, utilizatorii si setarile."
  if ($Port -le 0) { $Port = Get-TaskPort }
  if ($Port -le 0) {
    Warn "Nu am putut citi portul folosit pana acum."
    $Port = [int](Ask "Pe ce port ruleaza serverul tau?" "8200")
  } else {
    Ok "Pastrez portul $Port"
  }
} else {
  Say "Raspunde la cateva intrebari (Enter = valoarea implicita)."
  Write-Host ""
  if ($Port -le 0) { $Port = [int](Ask "Port web" "8200") }
  if ($Media -eq "") { $Media = Ask "Foldere cu filme/seriale (separate prin ;)" "D:\Media" }
  if ($AdminUser -eq "") { $AdminUser = Ask "Utilizator administrator" "admin" }
  if ($AdminPass -eq "") {
    $AdminPass = Ask "Parola administrator (Enter = generez una)" "" -Secret
    if ($AdminPass -eq "") {
      $AdminPass = -join ((48..57) + (65..90) + (97..122) | Get-Random -Count 12 | ForEach-Object { [char]$_ })
      $GenPass = $AdminPass
    } elseif ($AdminPass.Length -lt 4) { Die "Parola trebuie sa aiba minim 4 caractere." }
  }
  Write-Host ""
  Say "Optional - le poti completa si mai tarziu din Administrare -> Setari:"
  if ($TmdbKey -eq "") { $TmdbKey = Ask "Cheie TMDB (Enter = sari)" "" }
  if ($OsKey -eq "") { $OsKey = Ask "Cheie OpenSubtitles (Enter = sari)" "" }
}

if ($Port -lt 1 -or $Port -gt 65535) { Die "Port invalid: $Port" }

New-Item -ItemType Directory -Path $App, $Data, (Join-Path $App "static"), (Join-Path $App "ffmpeg") -Force | Out-Null
$Tmp = Join-Path $env:TEMP "cineverse-setup"
Remove-Item $Tmp -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Path $Tmp -Force | Out-Null

Stop-CineVerse

# ------------------------------------------------------------------ Python
$needPy = $true
if (Test-Path $PyExe) {
  try { $v = & $PyExe -c "import sys;print('%d.%d' % sys.version_info[:2])" 2>$null; if ($v -match '^3\.(1[0-9]|[89])$') { $needPy = $false } } catch {}
}
if ($needPy) {
  Say "Descarc Python $PyVer (aprox. 11 MB)..."
  $z = Join-Path $Tmp "python.zip"
  if (-not (Get-File $PyUrl $z "Python")) { Die "Nu am putut descarca Python. Verifica conexiunea la internet." }
  Remove-Item (Join-Path $App "python") -Recurse -Force -ErrorAction SilentlyContinue
  Expand-Archive -Path $z -DestinationPath (Join-Path $App "python") -Force
  # in pachetul 'embeddable' trebuie activat 'import site', altfel pip si pachetele nu se incarca
  Get-ChildItem (Join-Path $App "python") -Filter "*._pth" | ForEach-Object {
    $c = Get-Content $_.FullName
    ($c -replace '^\s*#\s*import\s+site\s*$', 'import site') + @("Lib\site-packages") |
      Select-Object -Unique | Set-Content $_.FullName -Encoding ASCII
  }
  $pth = Get-ChildItem (Join-Path $App "python") -Filter "*._pth" | Select-Object -First 1
  if ($pth -and -not ((Get-Content $pth.FullName) -match '^\s*import\s+site\s*$')) {
    Die "Nu am putut pregati Python (fisierul ._pth). Incearca din nou."
  }
  Say "Instalez pip..."
  $gp = Join-Path $Tmp "get-pip.py"
  if (-not (Get-File $PipUrls $gp "pip")) { Die "Nu am putut descarca pip." }
  & $PyExe $gp --no-warn-script-location *>$null
  & $PyExe -m pip --version *>$null
  if ($LASTEXITCODE -ne 0) { Die "Instalarea pip a esuat." }
  Ok "Python instalat"
} else {
  Ok "Python este deja instalat"
}

# ------------------------------------------------------------------ pachete Python
Say "Instalez pachetele Python (poate dura 1-2 minute)..."
& $PyExe -m pip install --upgrade pip --no-warn-script-location *>$null
$core = @("fastapi>=0.115", "uvicorn[standard]>=0.30", "httpx>=0.27")
& $PyExe -m pip install --upgrade --no-warn-script-location @core *>$null
if ($LASTEXITCODE -ne 0) { Die "Nu am putut instala pachetele de baza (fastapi/uvicorn/httpx)." }
foreach ($pkg in @("guessit>=3.8", "pychromecast>=14", "psutil>=5.9")) {
  & $PyExe -m pip install --upgrade --no-warn-script-location $pkg *>$null
  if ($LASTEXITCODE -ne 0) { Warn "Pachetul optional '$pkg' nu s-a instalat - functia asociata va fi indisponibila." }
}
Ok "Pachete Python instalate"

# ------------------------------------------------------------------ FFmpeg
$ffExe = Join-Path $App "ffmpeg\ffmpeg.exe"
if (-not (Test-Path $ffExe)) {
  Say "Descarc FFmpeg (aprox. 80 MB) - contine si suportul pentru placa video..."
  $z = Join-Path $Tmp "ffmpeg.zip"
  if (-not (Get-File $FfUrls $z "FFmpeg")) { Die "Nu am putut descarca FFmpeg. Verifica conexiunea la internet." }
  $ex = Join-Path $Tmp "ff"
  Expand-Archive -Path $z -DestinationPath $ex -Force
  $bins = Get-ChildItem $ex -Recurse -Include "ffmpeg.exe", "ffprobe.exe" -File
  if (-not $bins) { Die "Arhiva FFmpeg nu contine ffmpeg.exe." }
  foreach ($b in $bins) { Copy-Item $b.FullName (Join-Path $App "ffmpeg") -Force }
  Ok "FFmpeg instalat"
} else {
  Ok "FFmpeg este deja instalat"
}
if (-not (Test-Path (Join-Path $App "ffmpeg\ffprobe.exe"))) { Die "Lipseste ffprobe.exe - instalarea FFmpeg este incompleta." }

# ------------------------------------------------------------------ fisierele aplicatiei
Say "Scriu aplicatia in $App..."
$SERVER_PY = @'

'@
$INDEX_HTML = @'

'@
