RVNULk1GUEsFBgAAAAAMAAwAUgMAAACwAAAAAA==
'@
Write-B64 $SERVER_PY  (Join-Path $App "server.py")
Write-B64 $INDEX_HTML (Join-Path $App "static\index.html")
Write-B64 $ICON180    (Join-Path $App "static\icon-180.png")
Write-B64 $ICON192    (Join-Path $App "static\icon-192.png")
Write-B64 $ICON512    (Join-Path $App "static\icon-512.png")
Write-B64 $APK        (Join-Path $App "static\CineVerse.apk")

$hls = Join-Path $App "static\hls.min.js"
if (-not (Test-Path $hls) -or (Get-Item $hls).Length -lt 10000) {
  Say "Descarc playerul HLS..."
  if (-not (Get-File $HlsUrls $hls "hls.js")) {
    Remove-Item $hls -Force -ErrorAction SilentlyContinue
    Warn "hls.js va fi incarcat din CDN la rulare (e nevoie de internet pe dispozitivele care se uita)."
  }
}
Ok "Fisiere scrise"

# ------------------------------------------------------------------ configurare initiala
if (-not $IsUpdate) {
  Say "Configurez serverul..."
  $setup = @("$App\server.py", "setup", "--admin-user", $AdminUser, "--admin-pass", $AdminPass, "--media-dirs", $Media)
  if ($TmdbKey) { $setup += @("--tmdb-key", $TmdbKey) }
  if ($OsKey) { $setup += @("--os-key", $OsKey) }
  if ((Invoke-Py $setup -Quiet) -ne 0) { Die "Configurarea initiala a esuat." }
  Ok "Server configurat"
}

# ------------------------------------------------------------------ lansator + comenzi
$runCmd = Join-Path $App "run-cineverse.cmd"
@"
@echo off
rem Lansatorul folosit de sarcina programata Windows. Nu il sterge.
set "CINEVERSE_DATA=$Data"
set "CINEVERSE_FFMPEG_DIR=$App\ffmpeg"
set "PYTHONUNBUFFERED=1"
set "PYTHONUTF8=1"
if exist "$Data\cineverse.log" (
  for %%A in ("$Data\cineverse.log") do if %%~zA GTR 20000000 move /y "$Data\cineverse.log" "$Data\cineverse.log.1" >nul
)
"$App\python\python.exe" "$App\server.py" run --port $Port >> "$Data\cineverse.log" 2>&1
"@ | Set-Content $runCmd -Encoding ASCII

$ctl = Join-Path $App "cineverse.cmd"
@"
@echo off
rem Comenzi: cineverse start ^| stop ^| restart ^| status ^| log ^| open
if /I "%~1"=="start"   ( schtasks /Run /TN "$TaskName" & goto :eof )
if /I "%~1"=="stop"    ( schtasks /End /TN "$TaskName" & goto :eof )
if /I "%~1"=="restart" ( schtasks /End /TN "$TaskName" & timeout /t 3 /nobreak >nul & schtasks /Run /TN "$TaskName" & goto :eof )
if /I "%~1"=="status"  ( schtasks /Query /TN "$TaskName" /FO LIST & goto :eof )
if /I "%~1"=="log"     ( powershell -NoProfile -Command "Get-Content -Wait -Tail 60 '$Data\cineverse.log'" & goto :eof )
if /I "%~1"=="open"    ( start "" "http://localhost:$Port" & goto :eof )
echo Utilizare: cineverse [start^|stop^|restart^|status^|log^|open]
"@ | Set-Content $ctl -Encoding ASCII

$path = [Environment]::GetEnvironmentVariable("Path", "Machine")
if ($path -notlike "*$App*") {
  [Environment]::SetEnvironmentVariable("Path", ($path.TrimEnd(';') + ";" + $App), "Machine")
}

# ------------------------------------------------------------------ sarcina programata (porneste cu Windows)
Say "Inregistrez serviciul care porneste odata cu Windows..."
try { Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
$action    = New-ScheduledTaskAction -Execute "cmd.exe" -Argument "/c `"$runCmd`"" -WorkingDirectory $App
$trigger   = New-ScheduledTaskTrigger -AtStartup
$principal = New-ScheduledTaskPrincipal -UserId "SYSTEM" -LogonType ServiceAccount -RunLevel Highest
$settings  = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
              -StartWhenAvailable -MultipleInstances IgnoreNew `
              -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) `
              -ExecutionTimeLimit ([TimeSpan]::Zero)
try {
  Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $trigger `
    -Principal $principal -Settings $settings -Description "CineVerse by NetStreaming - server media" | Out-Null
} catch {
  Die "Nu am putut inregistra sarcina programata: $($_.Exception.Message)"
}
Ok "Serviciu inregistrat"

# ------------------------------------------------------------------ firewall
try {
  Get-NetFirewallRule -DisplayName "CineVerse*" -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue
  New-NetFirewallRule -DisplayName "CineVerse (web $Port)" -Direction Inbound -Action Allow `
    -Protocol TCP -LocalPort $Port -Profile Private, Domain | Out-Null
  New-NetFirewallRule -DisplayName "CineVerse (mDNS Google Cast)" -Direction Inbound -Action Allow `
    -Protocol UDP -LocalPort 5353 -Profile Private, Domain | Out-Null
  Ok "Firewall: port $Port si mDNS (Chromecast) permise in reteaua locala"
  $pub = @(Get-NetConnectionProfile -ErrorAction SilentlyContinue | Where-Object { $_.NetworkCategory -eq "Public" })
  if ($pub.Count -gt 0) {
    Warn "Reteaua '$($pub[0].Name)' este setata ca Publica, deci regula de firewall nu se aplica pe ea."
    Warn "Ca sa te poti conecta de pe alte dispozitive, treci-o pe Privata:"
    Warn "  Setari -> Retea si internet -> (reteaua ta) -> Retea privata"
  }
} catch {
  Warn "Nu am putut configura firewall-ul - deschide manual portul $Port daca nu te poti conecta de pe alt dispozitiv."
}

# ------------------------------------------------------------------ scurtatura in meniul Start
try {
  $lnk = Join-Path ([Environment]::GetFolderPath("CommonPrograms")) "CineVerse.lnk"
  $ws = New-Object -ComObject WScript.Shell
  $sc = $ws.CreateShortcut($lnk)
  $sc.TargetPath = "http://localhost:$Port"
  $sc.Description = "CineVerse by NetStreaming"
  $sc.Save()
} catch {}

# ------------------------------------------------------------------ pornire
Say "Pornesc serverul..."
Start-ScheduledTask -TaskName $TaskName
$up = $false
foreach ($i in 1..45) {
  Start-Sleep -Seconds 1
  try {
    $r = Invoke-WebRequest -Uri "http://127.0.0.1:$Port/" -UseBasicParsing -TimeoutSec 3
    if ($r.StatusCode -ge 200) { $up = $true; break }
  } catch {}
}

Remove-Item $Tmp -Recurse -Force -ErrorAction SilentlyContinue

if (-not $up) {
  Write-Host ""
  Warn "Serverul nu a raspuns in 45 de secunde."
  Warn "Vezi ce s-a intamplat:   type `"$Data\cineverse.log`""
  Write-Host ""
  Read-Host "Apasa Enter ca sa inchizi"
  exit 1
}

$ip = (Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue |
       Where-Object { $_.IPAddress -notlike "127.*" -and $_.IPAddress -notlike "169.254.*" -and
                      $_.InterfaceAlias -notmatch "vEthernet|Hyper-V|VMware|VirtualBox|WSL|Loopback" } |
       Sort-Object -Property SkipAsSource | Select-Object -First 1).IPAddress
if (-not $ip) { $ip = "localhost" }

Write-Host ""
Write-Host ("  " + ("=" * 62)) -ForegroundColor Green
Write-Host "   CineVerse by NetStreaming ruleaza!" -ForegroundColor Green
Write-Host ""
Write-Host "   In retea:      http://${ip}:$Port" -ForegroundColor White
Write-Host "   Pe acest PC:   http://localhost:$Port" -ForegroundColor White
if (-not $IsUpdate) {
  Write-Host ""
  Write-Host "   Utilizator:    $AdminUser" -ForegroundColor White
  if ($GenPass) { Write-Host "   Parola:        $GenPass   <-- noteaz-o acum!" -ForegroundColor Yellow }
}
Write-Host ""
Write-Host "   Comenzi:       cineverse start | stop | restart | status | log | open" -ForegroundColor Gray
Write-Host "   Adauga filme:  Administrare -> Biblioteca (sau editeaza folderele acolo)" -ForegroundColor Gray
Write-Host "   Jurnal:        $Data\cineverse.log" -ForegroundColor Gray
Write-Host "   Dezinstalare:  powershell -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Uninstall" -ForegroundColor Gray
Write-Host ("  " + ("=" * 62)) -ForegroundColor Green
Write-Host ""

if ($Media -match '^\\\\') {
  Write-Host ""
  Warn "Ai indicat un folder de retea ($Media)."
  Warn "Serverul ruleaza ca SYSTEM si nu vede folderele partajate din retea."
  Warn "Solutii: copiaza/monteaza continutul pe un disc local, sau deschide"
  Warn "  Task Scheduler -> '$TaskName' -> Properties -> schimba contul cu unul"
  Warn "  care are acces la share (bifeaza 'Run whether user is logged on or not')."
}

try { Start-Process "http://localhost:$Port" } catch {}
Read-Host "Apasa Enter ca sa inchizi"
